#!/bin/bash

# Generated by the PhyloPhere runner GUI — edit the project file and regenerate
# rather than hand-editing this file, unless you're making a one-off tweak.
#
# profile == 'slurm': submit this file with `sbatch` — SLURM sets
# SLURM_ARRAY_TASK_ID per array task and dispatch_phenotype below reads it once.
# profile == 'local': run this file directly with `bash` — no scheduler, no
# SLURM_ARRAY_TASK_ID, so it loops over every phenotype row itself and dispatches
# them sequentially instead.


# --- ENV ACTIVATION ---
set +u
if command -v micromamba >/dev/null 2>&1; then
    eval "$(micromamba shell hook --shell bash)"
    micromamba activate phylophere
elif [ -n "${CONDA_EXE:-}" ] || command -v conda >/dev/null 2>&1; then
    __base="$(conda info --base 2>/dev/null || dirname "$(dirname "${CONDA_EXE:-}")")"
    [ -f "$__base/etc/profile.d/conda.sh" ] && . "$__base/etc/profile.d/conda.sh"
    conda activate phylophere
fi
set -u

# --- GLOBAL RUN CONFIG ---
export RESUME="${RESUME:-0}"
export RUN_TOWER=false

if [ "false" = true ]; then
    export TAG="_toy"
    export TOY_MODE=true
    export TOY_N=""
    export CAAS_FULL_PERMS="100"
    # The draw budget must scale with the toy harvest target, not stay at the
    # full-run value: toy_mode subsamples alignments, never species, so the
    # permulation step still works on the full tree at the full acceptance
    # rate. 100 accepted needs well under 1k draws even under BM, so 20k is
    # generous headroom — and it caps a run that CANNOT fill the pool at ~1 min
    # instead of grinding through 1M draws plus two escalations before failing,
    # which would defeat the point of a smoke test.
    export MAX_TRIES="20000"
    export N_RANDOMIZATIONS="1000"
    export RER_PERM_BATCHES="10"
    export RER_PERMS_PER_BATCH="10"
else
    export TAG=""
    export TOY_MODE=false
    export TOY_N=""
    export CAAS_FULL_PERMS="${CAAS_FULL_PERMS:-1000}"
    export MAX_TRIES="100000"
    export N_RANDOMIZATIONS="1000000"
    export RER_PERM_BATCHES="10"
    export RER_PERMS_PER_BATCH="100"
fi

